<?php

declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/includes/errors.php';
require_once dirname(__DIR__, 2) . '/src/includes/app.php';
require_once dirname(__DIR__, 2) . '/src/function/teams_surface_provider.php';
$idUsuario = stridebr_require_login();
if (!stridebr_teams_enabled()) stridebr_error_document(404);
require_once dirname(__DIR__, 2) . '/src/config/pg_config.php';
$teamRef = trim((string) ($_GET['team'] ?? ''));
$seasonRef = trim((string) ($_GET['season'] ?? ''));
$context = stridebr_teams_surface_context($pdo, $idUsuario);
$teamContext = null;
foreach ((array) ($context['my_teams'] ?? []) as $candidate) if (($candidate['team']['ref'] ?? '') === $teamRef && ($candidate['season']['ref'] ?? '') === $seasonRef) $teamContext = $candidate;
if (!$teamContext) stridebr_error_document(404);
$roster = stridebr_teams_surface_roster($pdo, $idUsuario, $teamRef, $seasonRef);
if (!$roster) stridebr_error_document(404);
$today = new DateTimeImmutable('today');
$trainings = stridebr_teams_surface_trainings($pdo, $idUsuario, $today->format('Y-m-d'), $today->modify('+120 days')->format('Y-m-d'), $teamRef);
$competitions = stridebr_teams_surface_competitions($pdo, $idUsuario);
?>
